const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeElton = ee.Geometry.Point([46.65, 49.15]).buffer(5000);

  const start2004 = '2004-06-01';
  const end2004 = '2004-09-30';
  const start2009 = '2009-06-01';
  const end2009 = '2009-09-30';

  // Landsat 5 SR collection
  const getCollection = (startDate, endDate) => {
    return ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(lakeElton)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 20));
  };

  // 2. Data Acquisition & Check
  let col2004 = getCollection(start2004, end2004);
  let col2009 = getCollection(start2009, end2009);

  let size2004 = col2004.size().getInfo();
  let size2009 = col2009.size().getInfo();

  // Recovery logic for empty collections
  if (size2004 === 0 || size2009 === 0) {
    // Try widening date range
    const getWideCollection = (year) => {
      return ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(lakeElton)
        .filterDate(`${year}-01-01`, `${year}-12-31`)
        .filter(ee.Filter.lt('CLOUD_COVER', 50));
    };

    if (size2004 === 0) col2004 = getWideCollection(2004);
    if (size2009 === 0) col2009 = getWideCollection(2009);

    size2004 = col2004.size().getInfo();
    size2009 = col2009.size().getInfo();

    if (size2004 === 0 || size2009 === 0) {
      console.log(`2004 Images: ${size2004}`);
      console.log(`2009 Images: ${size2009}`);
      console.log("<answer>C1</answer>");
      return;
    }
  }

  console.log(`2004 Images: ${size2004}`);
  console.log(`2009 Images: ${size2009}`);

  // 3. Processing - Create median composites
  const getComposite = (collection) => {
    return collection
      .map(function(image) {
        // Apply scale factors for SR bands
        const opticalBands = image.select(['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7'])
          .multiply(0.0000275).add(-0.2);
        const thermalBand = image.select('ST_B6').multiply(0.00341802).add(149.0);
        return image.addBands(opticalBands, null, true)
          .addBands(thermalBand, null, true);
      })
      .median()
      .clip(lakeElton);
  };

  const composite2004 = getComposite(col2004);
  const composite2009 = getComposite(col2009);

  // Calculate visible band reflectance (average of B2, B3, B4)
  const calcReflectance = (image) => {
    const green = image.select('SR_B2');
    const red = image.select('SR_B3');
    const nir = image.select('SR_B4');
    return green.add(red).add(nir).divide(3);
  };

  const reflectance2004 = calcReflectance(composite2004);
  const reflectance2009 = calcReflectance(composite2009);

  // 4. Calculation - Get mean reflectance
  const reducer = ee.Reducer.mean();

  const stats2004 = reflectance2004.reduceRegion({
    reducer: reducer,
    geometry: lakeElton,
    scale: 1000,
    maxPixels: 1e9,
  }).getInfo();

  const stats2009 = reflectance2009.reduceRegion({
    reducer: reducer,
    geometry: lakeElton,
    scale: 1000,
    maxPixels: 1e9,
  }).getInfo();

  const mean2004 = stats2004[Object.keys(stats2004)[0]];
  const mean2009 = stats2009[Object.keys(stats2009)[0]];

  // Check for valid pixels
  if (mean2004 === null || mean2009 === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`2004 Mean SR: ${mean2004.toFixed(4)}`);
  console.log(`2009 Mean SR: ${mean2009.toFixed(4)}`);

  // Validate range (SR should be between -0.2 and 1.0 after scaling)
  if (mean2004 < -0.2 || mean2004 > 1.0 || mean2009 < -0.2 || mean2009 > 1.0) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (isNaN(mean2004) || isNaN(mean2009)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Answer based on increase
  if (mean2009 > mean2004) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
